use serde_json::{json,Value};use sha2::{Digest,Sha256};
use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};
const ROOT:&str="/tmp/zopro-prefix-stages";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn median(mut xs:Vec<f64>)->f64{assert!(!xs.is_empty());xs.sort_by(f64::total_cmp);let n=xs.len();if n%2==1{xs[n/2]}else{(xs[n/2]+xs[n/2-1])/2.}}
fn gm(xs:&[f64])->f64{assert!(!xs.is_empty());(xs.iter().map(|x|x.ln()).sum::<f64>()/xs.len()as f64).exp()}
fn prior()->BTreeSet<String>{let c=read("/tmp/zopro-prefix-pool/perf-plan.json");let mut p:BTreeSet<String>=serde_json::from_value(c["prior_proof_sha256"].clone()).unwrap();assert_eq!(p.len(),5844);for(rel,h)in read("/tmp/zopro-prefix-pool/performance/proof-inventory.json").as_object().unwrap(){assert_eq!(hash(Path::new("/tmp/zopro-prefix-pool/performance").join(rel)),h.as_str().unwrap());if rel.ends_with(".proof"){assert!(p.insert(h.as_str().unwrap().into()));}}assert_eq!(p.len(),5928);p}
fn cases()->Vec<Value>{read("/tmp/zopro-prefix-pool/perf-plan.json")["cases"].as_array().unwrap().iter().filter(|c|["1x2-w32","8x2-w32"].contains(&c["name"].as_str().unwrap())).cloned().collect()}
fn pins(){let r=Path::new(ROOT);let mut pins=BTreeMap::new();let mut changed=Vec::new();for(rel,h)in read("/tmp/zopro-grouping-module/production-source-manifest.json")["source_files_sha256"].as_object().unwrap(){let p=r.join("candidate").join(rel);let actual=hash(&p);if actual!=h.as_str().unwrap(){changed.push(rel.clone());}add(p,&mut pins);}assert_eq!(changed,vec!["crates/zopro-core/src/lib.rs","crates/zopro-core/src/msm_affine.rs","crates/zopro-prover/src/lib.rs","crates/zopro-zolana/src/lib.rs"]);for rel in ["crates/zopro-core/src/prefix_pool.rs","crates/zopro-core/src/stage_costs.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{add(r.join("candidate").join(rel),&mut pins);}for rel in ["instrument.rs","instrument.initial.rs","instrument.second.rs","instrument-repair.md","design.md","measure.rs","closeout.rs"]{add(r.join(rel),&mut pins);}save(r.join("source-pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"original_source_count":170,"unchanged_originals":166,"changed":changed,"new_core_modules":["prefix_pool.rs","stage_costs.rs"],"production_unchanged":true,"math_unchanged":true}));}
fn make(preflight:bool){let r=Path::new(ROOT);assert_eq!(read(r.join("native/result.json"))["status"],"complete");assert_eq!(read(r.join("native/on-core/tests.json"))["passed_tests"].as_array().unwrap().len(),116);let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("source-pins.json"))).unwrap();for rel in ["measure","closeout","source-audit.json","measure-tests.log","native-plan.json","native/result.json","native/on/artifacts.json"]{add(r.join(rel),&mut pins);}for a in [read(r.join("native/on/artifacts.json")),read("/tmp/zopro-grouping-module/native/candidate/artifacts.json")]{for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}add(a["binary"].as_str().unwrap(),&mut pins);}
 let base=read("/tmp/zopro-prefix-pool/perf-plan.json");for(p,h)in base["pins"].as_object().unwrap(){if p.contains("/registry/")||p.starts_with("/tmp/zopro-keys/"){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}}
 let binary=read(r.join("native/on/artifacts.json"))["binary"].as_str().unwrap().to_owned();let mut jobs=Vec::new();let mut steps=Vec::new();let blocks=if preflight{1}else{3};for block in 0..blocks{let mut cs=cases();let mut modes=if preflight{vec!["off","trace","pool"]}else{vec!["accepted","off","trace","pool"]};if !preflight{modes.rotate_left(block);if block%2==1{modes.reverse();cs.reverse();}}
 for c in cs{for mode in &modes{let name=format!("b{block}-{}-{mode}",c["name"].as_str().unwrap());let rounds=if preflight{1}else{31};let which=if preflight{"preflight"}else{"performance"};let proofroot=r.join("proofs").join(which).join(&name);let dir=proofroot.join(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap());let bin=if *mode=="accepted"{"/tmp/zopro-grouping-module/native/candidate-sdk"}else{&binary};let mut env=base["environment"].clone();env["ZOPRO_CPU_PREFIX_POOL"]=json!(if *mode=="pool"{"1"}else{"0"});if ["trace","pool"].contains(mode){env["ZOPRO_STAGE_OUTPUT"]=json!(dir.join("stages.json"));}for p in [bin,c["image"].as_str().unwrap(),c["request"].as_str().unwrap(),"/tmp/zopro-gnark-verify/verify","/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"]{add(p,&mut pins);}steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c","0-31",bin,c["image"],c["request"],rounds.to_string(),dir],"environment":env,"timeout_seconds":120}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",proofroot,"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":120}));jobs.push(json!({"case":c,"mode":mode,"block":block,"rounds":rounds,"name":name,"dir":dir}));}}}
 let which=if preflight{"preflight"}else{"performance"};if !preflight{assert_eq!(read(r.join("preflight-analysis.json"))["status"],"passed");for rel in ["preflight-analysis.json","preflight-proof-inventory.json","preflight/result.json"]{add(r.join(rel),&mut pins);}}
 save(r.join(format!("{which}-pins.json")),&json!(pins));save(r.join(format!("{which}-jobs.json")),&json!(jobs));save(r.join(format!("{which}-plan.json")),&json!({"version":1,"source_pins":r.join(format!("{which}-pins.json")),"environment":{},"steps":steps}));save(r.join("prior-identities.json"),&json!(prior()));println!("Prepared{which}:{}SDKprocesses;allhelpersprebuilt",jobs.len());}

fn event<'a>(es:&'a[Value],name:&str)->&'a Value{let matches:Vec<_>=es.iter().filter(|e|e["label"]==name).collect();assert_eq!(matches.len(),1,"{name}");matches[0]}
fn start(e:&Value)->u64{e["wall0"].as_u64().unwrap()}
fn end(e:&Value)->u64{e["wall1"].as_u64().unwrap()}
fn gap(a:u64,b:u64)->f64{assert!(b>=a,"negative interval");(b-a)as f64/1e6}
fn handoff(es:&[Value],caller:&str,worker:&str)->Value{let c=event(es,caller);let w=event(es,worker);json!({"dispatch_ms":gap(start(c),start(w)),"return_ms":gap(end(w),end(c)),"worker_ms":gap(start(w),end(w)),"caller_ms":gap(start(c),end(c))})}
fn inspect(v:&Value,pool:bool)->Value{let es=v["events"].as_array().unwrap();assert!(!es.is_empty()&&es.len()<=512);let mut stages=BTreeMap::new();let mut tids:BTreeMap<u64,Vec<&Value>>=BTreeMap::new();for(i,e)in es.iter().enumerate(){assert_eq!(e["id"],i);let wall=gap(start(e),end(e));let c0=e["cpu0"].as_u64().unwrap();let c1=e["cpu1"].as_u64().unwrap();assert!(c1>=c0);let cpu=(c1-c0)as f64/1e6;assert!(cpu<=wall+2.);tids.entry(e["tid"].as_u64().unwrap()).or_default().push(e);let label=e["label"].as_str().unwrap();assert!(stages.insert(label.to_owned(),json!({"wall_ms":wall,"calling_thread_cpu_ms":cpu})).is_none(),"duplicate{label}");}
 for es in tids.values_mut(){es.sort_by_key(|e|start(e));for(i,a)in es.iter().enumerate(){for b in &es[i+1..]{if start(b)<end(a){assert!(end(b)<=end(a),"crossing thread spans");}}}}
 for required in ["sdk.witness","sdk.serialization","prover.encode","prover.solve_rerandomized","prover.verify","core.external_entry","core.solve_wires","core.public_correction","core.canonical_wires","core.gather_queries","core.product_fft","core.query_join","core.encode_parts","core.assemble_randomized"]{event(es,required);}
 let handoffs=if pool{assert!(!stages.contains_key("core.worker_entry"));json!({"prefix":handoff(es,"core.prefix_install","core.prefix_worker"),"math":handoff(es,"core.math_join","core.math_worker")})}else{assert!(!stages.contains_key("core.prefix_worker"));let c=event(es,"core.external_entry");let w=event(es,"core.worker_entry");json!({"ordinary":json!({"dispatch_ms":gap(start(c),start(w)),"return_ms":gap(end(w),end(c)),"worker_ms":gap(start(w),end(w)),"caller_ms":gap(start(c),end(c))})})};
 json!({"records":es.len(),"stages":stages,"handoffs":handoffs,"threads":tids.len()})}
fn analyze(preflight:bool){let r=Path::new(ROOT);let which=if preflight{"preflight"}else{"performance"};assert_eq!(read(r.join(format!("{which}/result.json")))["status"],"complete");for(p,h)in read(r.join(format!("{which}-pins.json"))).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut prior=prior();let mut inventory:BTreeMap<String,String>=if preflight{BTreeMap::new()}else{serde_json::from_value(read(r.join("preflight-proof-inventory.json"))).unwrap()};for(p,h)in &inventory{assert_eq!(hash(p),*h);if p.ends_with(".proof"){assert!(prior.insert(h.clone()));}}
 let mut rows=Vec::new();let mut sdk=if preflight{0}else{24};let mut snapshots=0;
 for job in read(r.join(format!("{which}-jobs.json"))).as_array().unwrap(){let name=job["name"].as_str().unwrap();let mode=job["mode"].as_str().unwrap();let rounds=job["rounds"].as_u64().unwrap();let stdout=fs::read_to_string(r.join(which).join(name).join("stdout.log")).unwrap();let summary:Value=serde_json::from_str(stdout.lines().find_map(|x|x.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["rounds"],rounds);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],32);let samples:Vec<Value>=stdout.lines().filter_map(|x|x.strip_prefix("SAMPLE ")).map(|x|serde_json::from_str(x).unwrap()).collect();assert_eq!(samples.len(),rounds as usize);for(i,s)in samples.iter().enumerate(){assert_eq!(s["round"],i);assert!(s["ms"].as_f64().unwrap()>0.);}let dir=Path::new(job["dir"].as_str().unwrap());assert_eq!(fs::metadata(dir.join("0.proof")).unwrap().len(),164);assert_eq!(hash(dir.join("0.public")),job["case"]["public_sha256"].as_str().unwrap());assert!(prior.insert(hash(dir.join("0.proof"))));for rel in ["0.proof","0.public"]{let p=dir.join(rel);assert!(inventory.insert(p.display().to_string(),hash(p)).is_none());}let verify=fs::read_to_string(r.join(which).join(format!("verify-{name}/stdout.log"))).unwrap();assert!(verify.lines().last().unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));
 let mut metrics:BTreeMap<String,Vec<f64>>=BTreeMap::new();let mut observations=Vec::new();if ["trace","pool"].contains(&mode){assert_eq!(summary["recorder_storage_bytes"],32768);let captures=read(dir.join("stages.json"));assert_eq!(captures.as_array().unwrap().len(),rounds as usize);for(i,c)in captures.as_array().unwrap().iter().enumerate(){assert_eq!(c["round"],i);let o=inspect(c,mode=="pool"&&job["case"]["name"]=="1x2-w32");for(label,vs)in o["stages"].as_object().unwrap(){for(k,v)in vs.as_object().unwrap(){metrics.entry(format!("stage/{label}/{k}")).or_default().push(v.as_f64().unwrap());}}for(label,vs)in o["handoffs"].as_object().unwrap(){for(k,v)in vs.as_object().unwrap(){metrics.entry(format!("handoff/{label}/{k}")).or_default().push(v.as_f64().unwrap());}}observations.push(o);snapshots+=1;}}else{assert!(!dir.join("stages.json").exists());}let metrics:BTreeMap<_,_>=metrics.into_iter().map(|(k,vs)|(k,median(vs))).collect();sdk+=rounds+3;rows.push(json!({"case":job["case"]["name"],"mode":mode,"block":job["block"],"median_ms":median(samples.iter().map(|x|x["ms"].as_f64().unwrap()).collect()),"summary":summary,"samples":samples,"stage_medians":metrics,"observations":observations}));}
 save(r.join(if preflight{"preflight-proof-inventory.json"}else{"proof-inventory.json"}),&json!(inventory));if preflight{assert_eq!(sdk,24);assert_eq!(snapshots,4);assert_eq!(prior.len(),5934);save(r.join("preflight-analysis.json"),&json!({"status":"passed","sdk_requests":sdk,"distinct_gnark_exports":6,"trace_snapshots":snapshots,"rows":rows}));println!("Preflight24SDK6Gnark4snapshotsPASS");return;}
 assert_eq!(sdk,840);assert_eq!(snapshots,372);assert_eq!(prior.len(),5958);let mut cases_out=BTreeMap::new();let mut failures=Vec::new();for c in cases(){let name=c["name"].as_str().unwrap();let mut latency=BTreeMap::new();let mut stages:BTreeMap<String,Value>=BTreeMap::new();for mode in ["accepted","off","trace","pool"]{let rs:Vec<_>=rows.iter().filter(|x|x["case"]==name&&x["mode"]==mode).collect();assert_eq!(rs.len(),3);let ms=median(rs.iter().map(|x|x["median_ms"].as_f64().unwrap()).collect());latency.insert(mode,json!({"request_ms":ms,"max_process_RSS_mib":rs.iter().map(|x|x["summary"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.).fold(0.,f64::max),"cpu_ms_per_request":median(rs.iter().map(|x|(x["summary"]["user_cpu_ms"].as_f64().unwrap()+x["summary"]["system_cpu_ms"].as_f64().unwrap())/31.).collect()),"M5_CPU_speedup":c["reference"]["cpu_ms"].as_f64().unwrap()/ms,"M5_Metal_speedup":c["reference"]["metal_ms"].as_f64().unwrap()/ms}));let keys:Vec<_>=rs[0]["stage_medians"].as_object().unwrap().keys().cloned().collect();let mut out=BTreeMap::new();for key in keys{out.insert(key.clone(),median(rs.iter().map(|x|x["stage_medians"][&key].as_f64().unwrap()).collect()));}stages.insert(mode.into(),json!(out));}
 let mut ratios=BTreeMap::new();for(label,a,b,gate)in[("off_accepted","off","accepted",true),("trace_off","trace","off",true),("pool_trace","pool","trace",false)]{let mut ratios_vec=Vec::new();for block in 0..3{let ms=|m:&str|rows.iter().find(|x|x["case"]==name&&x["mode"]==m&&x["block"]==block).unwrap()["median_ms"].as_f64().unwrap();let ratio=ms(a)/ms(b);ratios_vec.push(ratio);if gate&&!(1./1.05..=1.05).contains(&ratio){failures.push(format!("{name} b{block} {label}={ratio}"));}}let med=median(ratios_vec.clone());if gate&&!(1./1.03..=1.03).contains(&med){failures.push(format!("{name} paired {label}={med}"));}ratios.insert(label,json!({"block_ratios":ratios_vec,"paired_median":med,"paired_geomean":gm(&ratios_vec)}));}cases_out.insert(name.to_owned(),json!({"latency":latency,"ratios":ratios,"stage_medians":stages,"supplied_reference":c["reference"]}));}
 save(r.join("analysis.json"),&json!({"status":"complete diagnostic","sdk_requests":840,"distinct_gnark_exports":30,"proof_public_members":60,"latency_trace_snapshots":372,"preflight_trace_snapshots":4,"timing_qualified":failures.is_empty(),"calibration_failures":failures,"cases":cases_out,"rows":rows,"next_prior_proof_count":5958,"adopted":false,"goal_achieved":false}));println!("Complete840SDK30Gnark372traces;timingqualified{}",failures.is_empty());}
fn main(){match std::env::args().nth(1).as_deref(){Some("pins")=>pins(),Some("prepare-preflight")=>make(true),Some("prepare-performance")=>make(false),Some("check-preflight")=>analyze(true),Some("analyze")=>analyze(false),_=>panic!("mode")}}
#[cfg(test)]mod tests{use super::*;fn e(n:&str,a:u64,b:u64)->Value{json!({"label":n,"wall0":a,"wall1":b})}#[test]fn handoff_intervals_partition_caller(){let h=handoff(&[e("caller",10,100),e("worker",20,90)],"caller","worker");assert_eq!(h["dispatch_ms"],0.00001);assert_eq!(h["return_ms"],0.00001);assert_eq!(h["worker_ms"],0.00007);}#[test]#[should_panic]fn handoff_rejects_worker_outside_caller(){handoff(&[e("caller",10,100),e("worker",9,90)],"caller","worker");}#[test]#[should_panic]fn duplicate_worker_is_rejected(){handoff(&[e("caller",10,100),e("worker",20,90),e("worker",30,50)],"caller","worker");}#[test]fn geometric_mean_and_even_median(){assert_eq!(median(vec![3.,1.]),2.);assert!((gm(&[2.,8.])-4.).abs()<1e-12);}}
